export interface SendOtpInput {
  /** 10-digit Indian mobile, already normalised. */
  mobile: string;
  /** Code generated by our server (handoff §3A rule 1). */
  code: string;
  ttlMinutes: number;
  /** Our OTP request id, echoed back in delivery webhooks (handoff §3A rule 5). */
  requestId: string;
}

export interface SendOtpResult {
  accepted: boolean;
  /** Raw provider response for debugging. Must not contain the code. */
  providerRef?: Record<string, unknown>;
}

/** Handoff §3A rule 4: SMS sits behind this interface so a fallback provider can be added. */
export interface SmsProvider {
  readonly name: string;
  sendOtp(input: SendOtpInput): Promise<SendOtpResult>;
}
